sealed interface Vehicle permits Car, Truck, Motorcycle { int wheelCount(); }
final class Car implements Vehicle { public int wheelCount() { return 4; } }
final class Truck implements Vehicle { public int wheelCount() { return 6; } }
final class Motorcycle implements Vehicle { public int wheelCount() { return 2; } }

Vehicle[] vs = { new Car(), new Truck(), new Motorcycle() };
for (Vehicle v : vs) System.out.println(v.wheelCount());

