sealed class Polygon implements Shape permits RegularPolygon {
    int sides; double sideLength;
    Polygon(int sides, double sideLength) { this.sides = sides; this.sideLength = sideLength; }
    public double area() { return 0.25 * sides * sideLength * sideLength / Math.tan(Math.PI / sides); }
}
final class RegularPolygon extends Polygon {
    RegularPolygon(int sides, double sideLength) { super(sides, sideLength); }
}

RegularPolygon pentagon = new RegularPolygon(5, 3);
System.out.println(pentagon.area());

