// Kompilator musi miec mozliwosc ZWERYFIKOWANIA calej hierarchii sealed NARAZ, zeby moc
// zagwarantowac (np. przy exhaustywnym switchu z Lekcji 21), ze zna WSZYSTKIE mozliwe podtypy.
// Gdyby permits mogl wskazywac klasy w dowolnym, oddzielnie kompilowanym module/pakiecie,
// ktos moglby dodac nowa implementacje w zupelnie innym projekcie/jarze bez ponownej kompilacji
// typu sealed - zamykajac gwarancje 'znam CALY zbior podtypow' na sile, co podwazyloby caly
// sens mechanizmu (i zepsulo bezpieczenstwo exhaustywnego switcha).

// Wybor: enum - warianty nie niosa zadnych roznych danych, tylko etykiete stanu.
enum OrderStatus {
    PENDING, PAID, CANCELLED;
    String describe() {
        return switch (this) {
            case PENDING -> "Oczekuje na platnosc";
            case PAID -> "Oplacone";
            case CANCELLED -> "Anulowane";
        };
    }
}
for (OrderStatus s : OrderStatus.values()) System.out.println(s + ": " + s.describe());

static double totalArea(Shape[] shapes) {
    double sum = 0;
    for (Shape s : shapes) sum += s.area();
    return sum;
}

Shape[] shapes = { new Circle(2), new Square(3), new EquilateralTriangle(4) };
System.out.println(totalArea(shapes));

static TrafficLight next(TrafficLight current) {
    return switch (current) {
        case RED -> TrafficLight.GREEN;
        case GREEN -> TrafficLight.YELLOW;
        case YELLOW -> TrafficLight.RED;
    };
}

TrafficLight t = TrafficLight.RED;
for (int i = 0; i < 4; i++) {
    System.out.println(t);
    t = next(t);
}

class OpenHexagon extends OpenShape {
    double side;
    OpenHexagon(double side) { this.side = side; }
    double area() { return 1.5 * Math.sqrt(3) * side * side; }
}
// OpenShape NIE jest sealed - to zwykla klasa abstrakcyjna, wiec KAZDY (w kazdym pakiecie)
// moze ja rozszerzyc bez ograniczen. Shape jest sealed z permits ograniczonym do Circle/
// Square/Triangle - dopisanie tam nowej klasy jest zablokowane przez kompilator, dopoki nie
// zostanie jawnie dodana do listy permits.

sealed interface PaymentMethod permits CreditCard, PayPal, BankTransfer {
    String describe();
}
final class CreditCard implements PaymentMethod {
    String number, expiry;
    CreditCard(String n, String e) { number = n; expiry = e; }
    public String describe() { return "Karta " + number + " wazna do " + expiry; }
}
final class PayPal implements PaymentMethod {
    String email;
    PayPal(String e) { email = e; }
    public String describe() { return "PayPal: " + email; }
}
final class BankTransfer implements PaymentMethod {
    String accountNumber;
    BankTransfer(String a) { accountNumber = a; }
    public String describe() { return "Przelew na konto: " + accountNumber; }
}

sealed interface Result<T> permits Success, Failure {}
final class Success<T> implements Result<T> { T value; Success(T v) { value = v; } }
final class Failure implements Result<Object> { String errorMessage; Failure(String m) { errorMessage = m; } }

static Result<Double> divide(double a, double b) {
    if (b == 0) return new Failure("Dzielenie przez zero");
    return new Success<>(a / b);
}

Result<Double> r = divide(10, 0);
if (r instanceof Success<Double> s) System.out.println(s.value);
else if (r instanceof Failure f) System.out.println(f.errorMessage);

abstract sealed class Employee permits Manager, Developer {
    String name;
    Employee(String name) { this.name = name; }
    abstract double salary();
}
final class Manager extends Employee {
    double base, bonusPercent;
    Manager(String n, double base, double bonusPercent) { super(n); this.base = base; this.bonusPercent = bonusPercent; }
    double salary() { return base * (1 + bonusPercent / 100); }
}
final class Developer extends Employee {
    double hourlyRate; int hours;
    Developer(String n, double rate, int hours) { super(n); hourlyRate = rate; this.hours = hours; }
    double salary() { return hourlyRate * hours; }
}

