static String describe(Shape shape) {
    if (shape instanceof Circle c) return "Kolo o promieniu " + c.radius;
    else if (shape instanceof Square s) return "Kwadrat o boku " + s.side;
    else if (shape instanceof Triangle t) return "Trojkat";
    return "Nieznany ksztalt";
}
// Mimo ze Shape jest sealed z dokladnie 3 podtypami, kompilator NIE WYMUSZA, by ten lancuch
// if/else if obsluzyl wszystkie trzy - gdybysmy zapomnieli o Triangle, kod i tak by sie
// skompilowal (z martwym 'return Nieznany ksztalt' na koncu). Dopiero switch pattern matching
// (Lekcja 21) potrafi wykorzystac wiedze o sealed do WYMUSZENIA kompletnosci przez kompilator.

