sealed interface Expr permits Num, Add, Multiply {}
record Num(double value) implements Expr {}
record Add(Expr left, Expr right) implements Expr {}
record Multiply(Expr left, Expr right) implements Expr {}

static double eval(Expr expr) {
    if (expr instanceof Num n) return n.value();
    if (expr instanceof Add a) return eval(a.left()) + eval(a.right());
    if (expr instanceof Multiply m) return eval(m.left()) * eval(m.right());
    throw new IllegalStateException();
}

Expr tree = new Multiply(new Add(new Num(2), new Num(3)), new Num(4));
System.out.println(eval(tree)); // 20.0

