sealed interface Shape3 permits Circle3, Rectangle3, Triangle3 {}
record Circle3(double radius) implements Shape3 {}
record Rectangle3(double w, double h) implements Shape3 {}
record Triangle3(double base, double height) implements Shape3 {}

class ShapeUtils {
    static double areaOf(Shape3 s) {
        if (s instanceof Circle3 c) return Math.PI * c.radius() * c.radius();
        if (s instanceof Rectangle3 r) return r.w() * r.h();
        if (s instanceof Triangle3 t) return 0.5 * t.base() * t.height();
        throw new IllegalStateException();
    }
    static double totalArea(List<Shape3> shapes) {
        double sum = 0;
        for (Shape3 s : shapes) sum += areaOf(s);
        return sum;
    }
    static Shape3 largestShape(List<Shape3> shapes) {
        Shape3 best = shapes.get(0);
        for (Shape3 s : shapes) if (areaOf(s) > areaOf(best)) best = s;
        return best;
    }
}

List<Shape3> shapes = List.of(new Circle3(2), new Rectangle3(3,4), new Triangle3(5,6), new Circle3(1), new Rectangle3(2,2));
System.out.println("Suma pol: " + ShapeUtils.totalArea(shapes));
System.out.println("Najwiekszy: " + ShapeUtils.largestShape(shapes));
